<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { http, unwrap, asList, errorMessage } from '../services/http.js'
import { connectSocket, getSocket } from '../services/socket.js'
const $q=useQuasar(),items=ref([]),page=ref(1),pages=ref(1),loading=ref(false),clearing=ref(false)
async function load(){loading.value=true;try{const value=unwrap(await http.get('/logs',{params:{page:page.value,limit:12}}));items.value=asList(value,'logs');pages.value=Math.max(1,Math.ceil(Number(value.total||value.pagination?.total||0)/12));if(page.value>pages.value){page.value=pages.value;await load()}}catch(error){$q.notify({type:'negative',message:errorMessage(error)})}finally{loading.value=false}}
function clear(rows){const ids=rows.map(row=>row.id||row._id);if(!ids.length)return;$q.dialog({title:'Remover eventos?',message:`Apagar ${ids.length} evento(s) selecionado(s) do console? Esta ação não remove contatos nem cancela entregas.`,cancel:true,persistent:true,ok:{label:'Remover',color:'negative'}}).onOk(async()=>{clearing.value=true;try{await http.post('/logs/clear',{ids,confirmation:'REMOVER HISTORICO SELECIONADO'});await load()}catch(error){$q.notify({type:'negative',message:errorMessage(error)})}finally{clearing.value=false}})}
function receive(log){if(page.value!==1)return;const id=log.id||log._id;items.value=[log,...items.value.filter(item=>(item.id||item._id)!==id)].slice(0,12)}
onMounted(()=>{load();connectSocket().on('log:created',receive)})
onBeforeUnmount(()=>getSocket().off('log:created',receive))
</script>
<template><q-card flat bordered class="system-events-console"><q-card-section><header><div><h2>Console de eventos</h2><p>Eventos em tempo real; dados sensíveis são ocultados pela API.</p></div><div class="events-actions"><q-btn flat no-caps color="negative" icon="delete_sweep" label="Limpar página atual" :disable="!items.length" :loading="clearing" @click="clear([...items])"/><q-btn flat round color="primary" icon="refresh" aria-label="Atualizar eventos" :loading="loading" @click="load"/></div></header><p v-if="!items.length&&!loading">Nenhum evento nesta página.</p><article v-for="log in items" :key="log.id||log._id"><q-badge :color="['error'].includes(log.level)?'negative':['warn','warning'].includes(log.level)?'warning':'primary'">{{log.level||'info'}}</q-badge><div class="event-main"><strong>{{log.message||log.title||log.event}}</strong><small>{{log.action||log.channel}}</small></div><time>{{new Date(log.createdAt||log.timestamp).toLocaleString('pt-BR')}}</time><q-btn flat round color="negative" icon="delete_outline" aria-label="Remover evento" :loading="clearing" @click="clear([log])"/></article><q-pagination v-if="pages>1" v-model="page" :max="pages" :max-pages="5" boundary-numbers class="q-mt-md" @update:model-value="load"/></q-card-section></q-card></template>
<style scoped>.system-events-console{border-radius:18px;color:#173d37;background:#fbfffe}.system-events-console header,.events-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.system-events-console h2{font-size:1.3rem;margin:0}.system-events-console p{font-size:.85rem;color:#59796f}.system-events-console article{display:flex;align-items:center;gap:12px;padding:13px 0;border-top:1px solid #dbeae4}.system-events-console .event-main{min-width:0;flex:1;overflow-wrap:anywhere}.system-events-console strong,.system-events-console small{display:block}.system-events-console strong{font-size:.85rem}.system-events-console small,.system-events-console time{font-size:.72rem;color:#56776a}@media(max-width:600px){.system-events-console article{flex-wrap:wrap;gap:8px}.system-events-console time{width:100%;order:1}.system-events-console .event-main{flex-basis:65%}.events-actions{width:100%}}</style>
